import sys

def solve(nums, k):
    d = {0: -1}
    curr_sum = 0
    for i, x in enumerate(nums):
        curr_sum += x
        rem = curr_sum % k if k != 0 else curr_sum
        if rem in d:
            if i - d[rem] >= 2: return True
        else:
            d[rem] = i
    return False

if __name__ == '__main__':
    input_data = sys.stdin.read().strip().split('\n')
    nums = list(map(int, input_data[0].split()))
    k = int(input_data[1])
    args = (nums, k)
    result = solve(*args) if 'args' in locals() else solve(nums)
    print(result)
